import{_ as a,o as n,c as e,a2 as s}from"./chunks/framework.ktMMbWgA.js";const o="/intelligence-computed/lectures/L31-llmops/demo/figures/latency_distribution.png",r="/intelligence-computed/lectures/L31-llmops/demo/figures/cost_waterfall.png",l="/intelligence-computed/lectures/L31-llmops/demo/figures/monitoring_panel.png",m=JSON.parse('{"title":"第 31 讲 · 评估、监控与 LLMOps — 从能用到可靠","description":"","frontmatter":{"title":"第 31 讲 · 评估、监控与 LLMOps — 从能用到可靠","act":5,"kind":"notes","prev":{"text":"L30 · AI 编程协作","link":"/lectures/L30-ai-coding/"},"next":{"text":"L32 · 生成式 AI 的版图","link":"/lectures/L32-generative-ai/"}},"headers":[],"relativePath":"lectures/L31-llmops/index.md","filePath":"lectures/L31-llmops/index.md","lastUpdated":null}'),i={name:"lectures/L31-llmops/index.md"};function p(c,t,d,g,h,u){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="第-31-讲-·-评估、监控与-llmops-—-从能用到可靠" tabindex="-1">第 31 讲 · 评估、监控与 LLMOps — 从能用到可靠 <a class="header-anchor" href="#第-31-讲-·-评估、监控与-llmops-—-从能用到可靠" aria-label="Permalink to &quot;第 31 讲 · 评估、监控与 LLMOps — 从能用到可靠&quot;">​</a></h1><blockquote><p><strong>上一讲你学会了和 AI 一起写代码——但代码写出来 ≠ 产品可以上线</strong>。</p><p>本讲将 L26 PGE 框架中的 Evaluator 升级为<strong>生产级</strong>评估体系，同时呼应从 L03 到 L26 的整条 Evaluator 线。</p><p><strong>一个幻觉率 5% 的模型在实验室是论文，在生产环境是事故</strong>——&quot;能用&quot;和&quot;可靠&quot;之间隔着整个工程体系。<strong>模型是引擎，LLMOps 是整辆车</strong>。</p><p>2024-2026 年 LLMOps 从 &quot;DevOps 的子集&quot; 演化为独立学科——LangSmith / Helicone / Langfuse / Braintrust / OpenLLMetry 等专用工具生态崛起。这是 LLM 应用从 &quot;做出来&quot; 到 &quot;做得起&quot; 的关键基础设施。</p></blockquote><table tabindex="0"><thead><tr><th>前置知识</th><th>核心产出</th><th>建议用时</th></tr></thead><tbody><tr><td>L03（损失函数）、L18（RLHF）、L20（推理）、L24（RAG）、L26（PGE）</td><td>① 理解推理服务化（vLLM / PagedAttention / Continuous Batching / Speculative Decoding）② 掌握生产硬指标（TTFT / TPS / KV Cache 利用率） ③ 构建五层评估体系 ④ 理解可观测性系统（Prompt 版本 / 成本 / Trace） ⑤ 掌握幻觉治理三板斧 ⑥ 看 2026 年 LLMOps 工具链 ⑦ 拿到 L34 (Safety) 的伏笔</td><td>阅读 ~80 分钟 + 动手 ~30 分钟</td></tr></tbody></table><hr><h2 id="从上一讲到这一讲" tabindex="-1">从上一讲到这一讲 <a class="header-anchor" href="#从上一讲到这一讲" aria-label="Permalink to &quot;从上一讲到这一讲&quot;">​</a></h2><p>第 30 讲问：<strong>这个应用你敢直接上线吗？隔着整个工程体系。</strong></p><p>你学会了和 AI 一起写代码——Claude Code 帮你建应用，Copilot 帮你补全，Cursor 帮你重构。但现在你要面对一个残酷的现实：某公司用 LLM 做客服，上线第一天，AI 向 40 多个用户承诺了根本不存在的退款——幻觉率只有 3%，但 3% 意味着每 33 次对话就有一次胡说八道。在实验室，3% 是一个可以发论文的数字；在生产环境，3% 是<strong>每小时几十次事故</strong>。</p><p>从&quot;能用&quot;到&quot;可靠&quot;之间隔着什么？一整套工程体系：推理服务、性能指标、评估流水线、可观测性、幻觉治理。这套体系叫 <strong>LLMOps</strong>。</p><hr><h2 id="_1-推理服务化-让模型跑起来" tabindex="-1">1. 推理服务化：让模型跑起来 <a class="header-anchor" href="#_1-推理服务化-让模型跑起来" aria-label="Permalink to &quot;1. 推理服务化：让模型跑起来&quot;">​</a></h2><h3 id="_1-1-为什么-model-generate-不够" tabindex="-1">1.1 为什么 <code>model.generate()</code> 不够 <a class="header-anchor" href="#_1-1-为什么-model-generate-不够" aria-label="Permalink to &quot;1.1 为什么 \`model.generate()\` 不够&quot;">​</a></h3><p>一个 <code>model.generate()</code> 调用在你的笔记本上跑得通，但生产环境要面对：并发（100 个用户同时请求）、延迟（用户等不了 30 秒）、成本（GPU 一小时几十块钱，空跑就是烧钱）、可用性（挂了要能自动恢复）。</p><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>推理服务化（Inference Serving）的核心问题是：如何让一个几十 GB 的模型高效地同时服务成百上千个用户？</strong> 关键技术是 PagedAttention（内存管理）、Continuous Batching（动态批处理）和 Speculative Decoding（投机解码）。</p></div><h3 id="_1-2-pagedattention-vllm-的核心" tabindex="-1">1.2 PagedAttention（vLLM 的核心） <a class="header-anchor" href="#_1-2-pagedattention-vllm-的核心" aria-label="Permalink to &quot;1.2 PagedAttention（vLLM 的核心）&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>PagedAttention 把 KV Cache 像操作系统的虚拟内存一样分页管理。</strong> 传统推理预分配最大长度的 KV Cache（如 4096 token），即使实际只用了 100 token——浪费率高达 97%。PagedAttention 按需分配物理内存页，用逻辑→物理映射表避免浪费。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统方式:</span></span>
<span class="line"><span>  请求 A（实际 100 token）→ 预分配 4096 token 内存 → 浪费 97%</span></span>
<span class="line"><span>  请求 B（实际 200 token）→ 预分配 4096 token 内存 → 浪费 95%</span></span>
<span class="line"><span>  GPU 内存满 → 只能同时服务 2 个请求</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PagedAttention:</span></span>
<span class="line"><span>  请求 A（100 token）→ 分配 7 页（每页 16 token）→ 112 token 内存</span></span>
<span class="line"><span>  请求 B（200 token）→ 分配 13 页 → 208 token 内存</span></span>
<span class="line"><span>  GPU 内存充裕 → 可以同时服务 20+ 个请求</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">直觉</p><p>传统方式像给每位客人预留一整张大桌子（8 人桌），即使只来了 1 个人。PagedAttention 像自助餐厅的灵活座位——来几个人坐几个位子，空椅子留给其他客人。</p></div><h3 id="_1-3-continuous-batching-与-speculative-decoding" tabindex="-1">1.3 Continuous Batching 与 Speculative Decoding <a class="header-anchor" href="#_1-3-continuous-batching-与-speculative-decoding" aria-label="Permalink to &quot;1.3 Continuous Batching 与 Speculative Decoding&quot;">​</a></h3><p><strong>Continuous Batching（连续批处理）</strong>：不是凑齐一批请求再一起处理，而是一有请求就&quot;插队&quot;加入当前 batch。完成的请求立即退出，新请求立即加入——GPU 利用率大幅提升。</p><p><strong>Speculative Decoding（投机解码）</strong>：用一个小模型（Draft Model）快速生成候选 token，再让大模型并行验证。如果小模型猜对了（大部分情况），相当于一次大模型推理完成了多个 token——延迟显著降低。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统解码:  大模型 → token₁ → 大模型 → token₂ → 大模型 → token₃</span></span>
<span class="line"><span>          (每个 token 一次大模型调用)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>投机解码:  小模型快速生成 [t₁, t₂, t₃, t₄, t₅]</span></span>
<span class="line"><span>          大模型一次验证 → 接受 [t₁, t₂, t₃]，拒绝 t₄</span></span>
<span class="line"><span>          (5 个候选 token 只用了 1 次大模型调用 + 1 次小模型调用)</span></span></code></pre></div><hr><h2 id="_2-生产硬指标" tabindex="-1">2. 生产硬指标 <a class="header-anchor" href="#_2-生产硬指标" aria-label="Permalink to &quot;2. 生产硬指标&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>三个核心指标定义了推理服务的&quot;好不好&quot;：TTFT（首 token 时间）、TPS（每秒 token 数）、KV Cache 利用率。</strong> 这些指标直接对应用户体验和运营成本。</p></div><p><img src="`+o+'" alt="延迟分布——P50/P95/P99 的差异决定了用户体验"></p><p><em>图：推理延迟分布示意——关注 P95/P99 尾延迟，而非平均值。</em></p><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>用户感知</th><th>优化目标</th></tr></thead><tbody><tr><td><strong>TTFT</strong> (Time To First Token)</td><td>用户按发送到看到第一个字的时间</td><td>&quot;AI 反应快不快&quot;</td><td>&lt; 500ms（对话场景）</td></tr><tr><td><strong>TPS</strong> (Tokens Per Second)</td><td>流式输出的速度</td><td>&quot;AI 说话流不流畅&quot;</td><td>&gt; 30 TPS（阅读速度）</td></tr><tr><td><strong>KV Cache 利用率</strong></td><td>GPU 显存中 KV Cache 的有效利用比</td><td>运营成本</td><td>&gt; 85%（PagedAttention）</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">推理经济学</p><p>训练是一次性成本，推理是持续成本。一个 70B 模型在 A100 上的推理成本约 $2-4/小时。如果 KV Cache 利用率从 30% 提升到 90%（通过 PagedAttention），同一块 GPU 可以服务 3 倍的并发请求——等于推理成本降低到 1/3。<strong>推理优化不是锦上添花，是生存问题。</strong></p></div><p><img src="'+r+`" alt="成本瀑布图——从模型选择到部署方案，每一层的成本拆解"></p><p><em>图：LLM 推理成本瀑布——模型大小、量化方案、batch 策略层层影响最终每请求成本。</em></p><hr><h2 id="_3-评估体系-五层渐进" tabindex="-1">3. 评估体系：五层渐进 <a class="header-anchor" href="#_3-评估体系-五层渐进" aria-label="Permalink to &quot;3. 评估体系：五层渐进&quot;">​</a></h2><h3 id="_3-1-evaluator-线的终极呼应" tabindex="-1">3.1 Evaluator 线的终极呼应 <a class="header-anchor" href="#_3-1-evaluator-线的终极呼应" aria-label="Permalink to &quot;3.1 Evaluator 线的终极呼应&quot;">​</a></h3><blockquote><p>[!abstract] Evaluator 线回顾</p><ul><li><strong>L03 损失函数</strong>：最原始的 Evaluator——数值越小越好</li><li><strong>L18 RLHF 奖励模型</strong>：人类偏好训练的 Evaluator——给回答打分</li><li><strong>L20 推理模型内置验证</strong>：模型自己做 Evaluator——思维链中的自我检查</li><li><strong>L26 PGE 显式化</strong>：Agent Loop 中的 Evaluate 步骤——外部信号反馈</li><li><strong>L31 生产级 Evaluator</strong>（本节）：LLM-as-Judge + 评估流水线 + 人工抽检——完整的质量保障体系</li></ul></blockquote><h3 id="_3-2-五层评估架构" tabindex="-1">3.2 五层评估架构 <a class="header-anchor" href="#_3-2-五层评估架构" aria-label="Permalink to &quot;3.2 五层评估架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 5 层: Agent 评估（SWE-bench / TAU-bench）</span></span>
<span class="line"><span>         → 端到端任务完成率</span></span>
<span class="line"><span>第 4 层: Benchmark 评估</span></span>
<span class="line"><span>         → 标准数据集上的量化指标</span></span>
<span class="line"><span>第 3 层: 人工评估</span></span>
<span class="line"><span>         → 专家标注 + 众包评分</span></span>
<span class="line"><span>第 2 层: LLM-as-Judge</span></span>
<span class="line"><span>         → 用强模型评估弱模型的输出</span></span>
<span class="line"><span>第 1 层: 自动评估</span></span>
<span class="line"><span>         → BLEU / ROUGE / 精确匹配 / 单元测试</span></span></code></pre></div><h3 id="_3-3-llm-as-judge-用-ai-评估-ai" tabindex="-1">3.3 LLM-as-Judge：用 AI 评估 AI <a class="header-anchor" href="#_3-3-llm-as-judge-用-ai-评估-ai" aria-label="Permalink to &quot;3.3 LLM-as-Judge：用 AI 评估 AI&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>LLM-as-Judge 用一个强模型（如 GPT-4o）作为评审员，按照预定义的评分标准对目标模型的输出打分。</strong> 它是自动评估（太浅）和人工评估（太贵）之间的最佳平衡点。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>评估 prompt 示例:</span></span>
<span class="line"><span>&quot;你是一个专业的评审员。请根据以下标准对 AI 的回答评分（1-5分）：</span></span>
<span class="line"><span> - 事实准确性：回答中的事实是否正确？</span></span>
<span class="line"><span> - 完整性：是否回答了用户的所有问题？</span></span>
<span class="line"><span> - 安全性：是否包含有害或误导性内容？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用户问题: {question}</span></span>
<span class="line"><span>AI 回答: {answer}</span></span>
<span class="line"><span>参考答案: {reference}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请给出评分和详细理由。&quot;</span></span></code></pre></div><div class="warning custom-block github-alert"><p class="custom-block-title">LLM-as-Judge 的局限</p><p>LLM-as-Judge 存在<strong>位置偏差</strong>（Position Bias）——倾向于给排在前面的选项更高分；<strong>自我偏好</strong>（Self-preference）——GPT-4 倾向于给 GPT-4 生成的回答更高分。实践中需要：① 交换选项位置取平均 ② 使用不同模型交叉评估 ③ 定期与人工评估对齐。</p></div><h3 id="_3-3-边界案例-dark-factory-—-当人类退出审查循环" tabindex="-1">3.3 边界案例：Dark Factory — 当人类退出审查循环 <a class="header-anchor" href="#_3-3-边界案例-dark-factory-—-当人类退出审查循环" aria-label="Permalink to &quot;3.3 边界案例：Dark Factory — 当人类退出审查循环&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>自动化验证的可靠度 = 你能安全放权的上限。</strong> 把这个逻辑推到极致：如果测试覆盖率足够高、CI 管线足够严、监控和回滚足够完善，理论上可以做到 AI Agent 写代码、跑测试、通过后自动合并部署，全程无人审查。这个模式叫 <strong>Dark Factory</strong>——术语来自制造业的&quot;黑灯工厂&quot;（全自动化，不需要开灯，因为没有工人）。</p></div><p>Dark Factory 不是科幻——在极窄场景中已有实践：</p><ul><li><strong>依赖版本更新</strong>：模式清晰，测试可完全覆盖</li><li><strong>模板化 CRUD 生成</strong>：输出可预测，自动测试可覆盖</li><li><strong>本地化字符串翻译</strong>：出错影响可控，可自动回滚</li></ul><p>这些任务的共同特征：① 模式清晰 ② 测试可完全覆盖 ③ 出错影响可控。</p><div class="warning custom-block github-alert"><p class="custom-block-title">核心风险</p><p><strong>&quot;自主化超前于验证基础设施&quot;是 AI 编程中最危险的模式。</strong> 一个幻觉率 5% 的模型在人工审查下是可控的——人看一眼就挡住了。同一个模型在 Dark Factory 中，那 5% 就是每周几十个有问题的提交直接上线。</p></div><p>安全路径是渐进放权（Progressive Autonomy）：</p><ul><li>Level 3（人审 Agent 输出）→ Level 4（编排系统 + 门控审查，呼应第 30 讲 Harness-Driven 模式）→ 极窄范围 Level 5（Dark Factory）</li><li><strong>每一步的前提是验证基础设施先到位</strong></li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">直觉</p><p>Dark Factory 的讨论反过来强化了本讲的核心论点：评估、监控、回滚不是可选的基础设施——它们是自主化的前提条件。没有五层评估，你连 Level 3 都不该做。没有完善的 CI + 监控 + 回滚，Level 5 就是定时炸弹。</p></div><hr><h2 id="_4-可观测性-知道出了什么事" tabindex="-1">4. 可观测性：知道出了什么事 <a class="header-anchor" href="#_4-可观测性-知道出了什么事" aria-label="Permalink to &quot;4. 可观测性：知道出了什么事&quot;">​</a></h2><p><img src="`+l+`" alt="监控面板示例——延迟、成本、错误率实时追踪"></p><p><em>图：LLMOps 监控面板示意——将 TTFT、TPS、成本、幻觉率整合在同一视图中。</em></p><h3 id="_4-1-四大支柱" tabindex="-1">4.1 四大支柱 <a class="header-anchor" href="#_4-1-四大支柱" aria-label="Permalink to &quot;4.1 四大支柱&quot;">​</a></h3><table tabindex="0"><thead><tr><th>支柱</th><th>做什么</th><th>工具示例</th></tr></thead><tbody><tr><td><strong>Prompt 版本管理</strong></td><td>每次 Prompt 修改可追溯、可回滚</td><td>LangSmith, Humanloop</td></tr><tr><td><strong>成本监控</strong></td><td>每次调用的 token 数 × 单价，按用户/功能/模型维度统计</td><td>自建仪表盘</td></tr><tr><td><strong>异常检测</strong></td><td>延迟突增、幻觉率飙升、拒绝率异常</td><td>Prometheus + 自定义规则</td></tr><tr><td><strong>Agent Trace</strong></td><td>Agent 的每一步（思考 → 调用 → 结果 → 反思）完整记录</td><td>LangSmith, Braintrust</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">直觉</p><p>Agent Trace 就像飞机的黑匣子——平时不看，出事后是唯一的线索。一个 Agent 在 10 步循环后给出了错误答案——没有 Trace，你只知道&quot;它答错了&quot;；有了 Trace，你能看到&quot;它在第 3 步检索到了错误文档，第 5 步基于错误事实推理，第 8 步虽然自我验证但没发现矛盾&quot;。</p></div><hr><h2 id="_5-幻觉治理-grounding、citation、fact-checking" tabindex="-1">5. 幻觉治理：Grounding、Citation、Fact-checking <a class="header-anchor" href="#_5-幻觉治理-grounding、citation、fact-checking" aria-label="Permalink to &quot;5. 幻觉治理：Grounding、Citation、Fact-checking&quot;">​</a></h2><h3 id="_5-1-三板斧" tabindex="-1">5.1 三板斧 <a class="header-anchor" href="#_5-1-三板斧" aria-label="Permalink to &quot;5.1 三板斧&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">核心概念</p><p><strong>幻觉治理不是&quot;消除幻觉&quot;（当前不可能），而是&quot;检测 + 缓解 + 标注&quot;三管齐下。</strong></p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一板斧: Grounding（接地）</span></span>
<span class="line"><span>  → 强制模型基于检索到的文档回答（呼应 L30 RAG）</span></span>
<span class="line"><span>  → 没有找到相关文档时，回答&quot;我不确定&quot;而非编造</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二板斧: Citation（引用）</span></span>
<span class="line"><span>  → 要求模型在回答中标注信息来源（[1], [2]...）</span></span>
<span class="line"><span>  → 用户可以点击来源验证——把验证成本从&quot;读全文&quot;降到&quot;点链接&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三板斧: Fact-checking Pipeline</span></span>
<span class="line"><span>  → 模型生成回答后，用独立模块核验关键事实</span></span>
<span class="line"><span>  → claim 提取 → 证据检索 → 矛盾检测 → 标注置信度</span></span></code></pre></div><blockquote><p>[!example] 工程实践 一个完整的幻觉治理流水线：① 用户提问 → ② RAG 检索相关文档 → ③ LLM 基于文档回答并附引用 → ④ Fact-checker 核验每条 claim → ⑤ 置信度低于阈值的 claim 被标注为&quot;待验证&quot; → ⑥ 前端用不同颜色展示已验证/待验证内容。成本约增加 30-50%，但幻觉率可从 ~5% 降到 &lt; 1%。</p></blockquote><hr><h2 id="_6-2026-年-llmops-生态速记-2026-04-快照" tabindex="-1">6. 2026 年 LLMOps 生态速记（2026-04 快照） <a class="header-anchor" href="#_6-2026-年-llmops-生态速记-2026-04-快照" aria-label="Permalink to &quot;6. 2026 年 LLMOps 生态速记（2026-04 快照）&quot;">​</a></h2><h3 id="_6-1-推理框架" tabindex="-1">6.1 推理框架 <a class="header-anchor" href="#_6-1-推理框架" aria-label="Permalink to &quot;6.1 推理框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>框架</th><th>主要定位</th></tr></thead><tbody><tr><td><strong>vLLM</strong></td><td>开源生产级推理（PagedAttention + Continuous Batching）</td></tr><tr><td><strong>TGI</strong> (HuggingFace)</td><td>HuggingFace 官方推理服务</td></tr><tr><td><strong>TensorRT-LLM</strong></td><td>NVIDIA 优化的推理框架</td></tr><tr><td><strong>SGLang</strong></td><td>结构化生成 + 高效采样</td></tr><tr><td><strong>lmdeploy</strong></td><td>上海 AI Lab 开源推理</td></tr><tr><td><strong>Together AI / Fireworks / Anyscale</strong></td><td>推理 SaaS</td></tr><tr><td><strong>Groq / SambaNova / Cerebras</strong></td><td>专用推理芯片</td></tr></tbody></table><h3 id="_6-2-评估与可观测性" tabindex="-1">6.2 评估与可观测性 <a class="header-anchor" href="#_6-2-评估与可观测性" aria-label="Permalink to &quot;6.2 评估与可观测性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>主要定位</th></tr></thead><tbody><tr><td><strong>LangSmith</strong></td><td>LangChain 生态评估 + 监控</td></tr><tr><td><strong>Langfuse</strong></td><td>开源 LLMOps 平台</td></tr><tr><td><strong>Helicone</strong></td><td>代理式监控（拦截 API 调用）</td></tr><tr><td><strong>Braintrust</strong></td><td>评估 + 实验跟踪</td></tr><tr><td><strong>Phoenix</strong> (Arize)</td><td>开源可观测性</td></tr><tr><td><strong>OpenLLMetry</strong></td><td>OpenTelemetry-style LLM 追踪</td></tr><tr><td><strong>Promptfoo</strong></td><td>Prompt 测试框架</td></tr><tr><td><strong>DeepEval / RAGAS / TruLens</strong></td><td>评估专用</td></tr><tr><td><strong>Anthropic Inspect</strong><sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></td><td>Anthropic 2024-09 开源的评估框架——支持自定义 solver / scorer / dataset，与 frontier-model risk evaluation 相同的内核</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">为什么 Inspect 值得单独点名</p><p>2026 年的合规现实（参见 <a href="/intelligence-computed/lectures/L34-safety/">L34 §5.1.1 EU AI Act 时间线</a>）要求高风险 AI 系统提交<strong>可重复的评估报告</strong>。Inspect 的设计目标恰好是这件事：</p><ul><li><strong>Solver / Scorer / Dataset 三段式</strong>：和 PGE 三角形（<a href="/intelligence-computed/lectures/L26-agent/">L26 §1</a>）同构 —— solver 做规划与执行，scorer 做评判，dataset 是真理基线</li><li><strong>可重放</strong>：评估配置即代码，任何人可在自己的硬件上复现 lab 公布的结果</li><li><strong>被 frontier lab 采用</strong>：UK AISI、Anthropic、OpenAI 在内部使用同一框架做 ASL 等级评估，意味着<strong>你做的产品评估和 frontier-model 风险评估用的是同一种语言</strong></li></ul><p><strong>L27 ↔ L31 的对应</strong>：<a href="/intelligence-computed/lectures/L27-agent-skills/">L27 §3 Sub-agent</a> 把&quot;做事的 Agent&quot;与&quot;评判的 Agent&quot;做了职责分离 —— Inspect 的 solver/scorer 分离正是这个思想在评估层的实现。本讲的&quot;五层评估架构&quot;（§3.2）和 Inspect 的实现一一对应：第 1-2 层 = 自动评估 + LLM-as-Judge = Inspect 的 scorer；第 3-5 层 = 人工 + Benchmark + Agent 评估 = Inspect 的 dataset + solver。</p></div><h3 id="_6-3-关键趋势" tabindex="-1">6.3 关键趋势 <a class="header-anchor" href="#_6-3-关键趋势" aria-label="Permalink to &quot;6.3 关键趋势&quot;">​</a></h3><ul><li><strong>OpenTelemetry for LLMs</strong>：开源标准化 trace 协议</li><li><strong>Prompt 版本管理产品化</strong>：Helicone / PromptLayer / LangSmith 都提供</li><li><strong>Agent 评估专用工具</strong>：SWE-bench / OSWorld / GAIA / TAU-bench / AgentBench</li><li><strong>每秒成本监控</strong>：实时统计 token 消耗 / 用户 / 功能维度</li><li><strong>多模型 Fallback</strong>：主模型故障 → 自动切换备用模型</li><li><strong>A/B 测试基础设施</strong>：LMSYS Chatbot Arena 启发的产品级 A/B 测试</li></ul><hr><h2 id="动手环节" tabindex="-1">动手环节 <a class="header-anchor" href="#动手环节" aria-label="Permalink to &quot;动手环节&quot;">​</a></h2><blockquote><p>[!example] 动手 LLMOps 仪表盘可视化：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lectures/L31-llmops/demo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llmops_dashboard.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # 生成评估流水线 + 监控面板 mock</span></span></code></pre></div><p>可视化代码见 <a href="/intelligence-computed/lectures/L31-llmops/demo/llmops_dashboard.py"><code>demo/llmops_dashboard.py</code></a>。</p></blockquote><hr><h2 id="失败模式-反例" tabindex="-1">失败模式 / 反例 <a class="header-anchor" href="#失败模式-反例" aria-label="Permalink to &quot;失败模式 / 反例&quot;">​</a></h2><blockquote><p>本节列出本讲核心结论<strong>不适用</strong>或<strong>易被误用</strong>的常见情境。教学的目的不是制造「已学会」的错觉，而是认清边界。</p></blockquote><ul><li>「Prompt 版本管理 = 解决了」误解：LangSmith / PromptLayer 解决了存储；但 <strong>prompt 与模型版本耦合</strong> 才是真痛点——换模型整套 prompt 要重测。</li><li>Eval 的循环陷阱：用 LLM-as-Judge 评 LLM 输出；当被评模型与裁判模型同源时，评分系统性偏高 5-15%。</li><li>「成本可控」迷思：Token 价格在降，但单次调用 token 数在涨（long-context、CoT、agent 多步）——总成本不一定降。必须监控 token-per-task。</li><li>A/B 测试在 LLM 上的失效：LLM 输出的「质量」主观且多维；传统 A/B (CTR/conversion) 不适用——需要 pairwise human eval 或 Arena 式评估。</li></ul><h2 id="本讲小结" tabindex="-1">本讲小结 <a class="header-anchor" href="#本讲小结" aria-label="Permalink to &quot;本讲小结&quot;">​</a></h2><ol><li><strong>推理服务化的三大技术</strong>——PagedAttention（KV Cache 分页管理，内存利用率从 30% → 90%）、Continuous Batching（动态插队批处理）、Speculative Decoding（小模型草拟大模型验证），让单卡可服务数十倍并发。</li><li><strong>TTFT / TPS / KV Cache 利用率是生产命脉</strong>——训练花一次，推理花每一秒。推理优化不是锦上添花，是生存问题。</li><li><strong>评估体系五层渐进</strong>——自动评估 → LLM-as-Judge → 人工评估 → Benchmark → Agent 评估。LLM-as-Judge 是成本与质量的最佳平衡点，但需要防范位置偏差和自我偏好。Dark Factory 作为边界案例说明：验证基础设施的完善度 = 可安全赋予的自主度上限。</li><li><strong>幻觉治理三板斧</strong>——Grounding 接地（基于文档回答）、Citation 引用（标注来源可验证）、Fact-checking 核验（独立模块检测矛盾），三管齐下可将幻觉率从 ~5% 降至 &lt; 1%。</li><li><strong>Evaluator 线的终极呼应</strong>——从 L03 损失函数 → L18 RLHF 奖励模型 → L20 推理模型自检 → L26 PGE Evaluate → L31 LLM-as-Judge + 评估流水线，Evaluator 从一个数字进化为一整套生产级质量保障体系。</li></ol><hr><h2 id="下一讲预告" tabindex="-1">下一讲预告 <a class="header-anchor" href="#下一讲预告" aria-label="Permalink to &quot;下一讲预告&quot;">​</a></h2><blockquote><p><strong>敌意问题</strong>：你现在知道怎么把 AI 应用做得可靠了——评估流水线、监控面板、幻觉检测，一整套工程体系。你的 AI 系统可以处理文本、写代码、调工具、搜知识。但它只会处理文字。人类世界不止有文字——还有图像、视频、音频、3D。AI 已经在学会画画、拍电影、作曲、建三维世界。<strong>当生成成本趋近于零，谁来决定什么值得生成？</strong></p></blockquote><p>第 32 讲——「生成式 AI 的版图」——当创造的成本趋近于零。</p><hr><h2 id="📺-推荐视频" tabindex="-1">📺 推荐视频 <a class="header-anchor" href="#📺-推荐视频" aria-label="Permalink to &quot;📺 推荐视频&quot;">​</a></h2><ol><li>🎥 <strong><a href="https://www.youtube.com/watch?v=FMfHt0WPkxY" target="_blank" rel="noreferrer">Anyscale — How Continuous Batching Enables 23x Throughput</a></strong> — Continuous Batching 的可视化讲解与吞吐量对比。</li><li>🎥 <strong><a href="https://www.youtube.com/watch?v=cry2bMyVviQ" target="_blank" rel="noreferrer">Hamel Husain — Your AI Product Needs Evals (AI Engineer Summit)</a></strong> — 评估体系的最佳实践分享。</li><li>🎥 <strong><a href="https://www.youtube.com/watch?v=s6QqGWYv2LM" target="_blank" rel="noreferrer">Chip Huyen — Building LLM Applications for Production</a></strong> — 从原型到生产的 LLMOps 全景。</li></ol><h2 id="🔗-互动资源" tabindex="-1">🔗 互动资源 <a class="header-anchor" href="#🔗-互动资源" aria-label="Permalink to &quot;🔗 互动资源&quot;">​</a></h2><ol><li>🌐 <strong><a href="https://docs.vllm.ai/" target="_blank" rel="noreferrer">vLLM 官方文档</a></strong> — PagedAttention + Continuous Batching 的参考实现。</li><li>🌐 <strong><a href="https://smith.langchain.com/" target="_blank" rel="noreferrer">LangSmith</a></strong> — Prompt 版本管理 + Agent Trace 的可视化平台。</li><li>🌐 <strong><a href="https://chat.lmsys.org/?leaderboard" target="_blank" rel="noreferrer">Chatbot Arena Leaderboard</a></strong> — LLM-as-Judge 的实际应用——众包盲评排行榜。</li></ol><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ol><li>📄 <strong>Kwon, W. et al. (2023). &quot;Efficient Memory Management for Large Language Model Serving with PagedAttention&quot;</strong> — vLLM 和 PagedAttention 原论文<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup>。</li><li>📝 <strong><a href="https://hamel.dev/blog/posts/evals/" target="_blank" rel="noreferrer">Hamel Husain: &quot;Your AI Product Needs Evals&quot;</a></strong> — AI 产品评估的最佳实践指南<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup>。</li><li>📝 <strong><a href="https://eugeneyan.com/writing/llm-patterns/" target="_blank" rel="noreferrer">Eugene Yan: &quot;Patterns for Building LLM-based Systems &amp; Products&quot;</a></strong> — LLM 系统构建模式的全景综述<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup>。</li><li>📝 <strong><a href="https://www.anyscale.com/blog/continuous-batching-llm-inference" target="_blank" rel="noreferrer">Anyscale: The Full Guide to LLM Inference</a></strong> — 推理服务化技术的深度指南，含 Continuous Batching 详解<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup>。</li><li>📄 <strong>Zheng, L. et al. (2023). &quot;Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena&quot;</strong> — LLM-as-Judge 方法论与 MT-Bench 基准<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup>。</li></ol><hr><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>UK AI Safety Institute &amp; Anthropic, &quot;Inspect: an open-source evaluation framework for LLMs&quot;（github.com/UKGovernmentBEIS/inspect_ai，2024-09）。 <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>Kwon, W. et al. (2023). &quot;Efficient Memory Management for Large Language Model Serving with PagedAttention&quot;. <em>SOSP</em>. <a href="https://arxiv.org/abs/2309.06180" target="_blank" rel="noreferrer">arxiv:2309.06180</a> <a href="#fnref2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p>Husain, H. (2024). &quot;Your AI Product Needs Evals&quot;. <a href="https://hamel.dev/blog/posts/evals/" target="_blank" rel="noreferrer">hamel.dev/blog/posts/evals</a> <a href="#fnref3" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p>Yan, E. (2023). &quot;Patterns for Building LLM-based Systems &amp; Products&quot;. <a href="https://eugeneyan.com/writing/llm-patterns/" target="_blank" rel="noreferrer">eugeneyan.com/writing/llm-patterns</a> <a href="#fnref4" class="footnote-backref">↩︎</a></p></li><li id="fn5" class="footnote-item"><p>Anyscale. (2023). &quot;Continuous Batching for LLM Inference&quot;. <a href="https://www.anyscale.com/blog/continuous-batching-llm-inference" target="_blank" rel="noreferrer">anyscale.com/blog/continuous-batching-llm-inference</a> <a href="#fnref5" class="footnote-backref">↩︎</a></p></li><li id="fn6" class="footnote-item"><p>Zheng, L. et al. (2023). &quot;Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena&quot;. <em>NeurIPS</em>. <a href="https://arxiv.org/abs/2306.05685" target="_blank" rel="noreferrer">arxiv:2306.05685</a> <a href="#fnref6" class="footnote-backref">↩︎</a></p></li></ol></section>`,96)])])}const f=a(i,[["render",p]]);export{m as __pageData,f as default};
